        if any(lines[x + i][y] != '+' for i in range(1, side_length)):
            return False
        if any(lines[x][y + i] != '+' for i in range(1, side_length)):
            return False
        if any(lines[x + i][y + i] != '+' for i in range(1, side_length)):
            return False
        if any(lines[x + i][y - i] != '+' for i in range(1, side_length)):
            return False
        return True

