    # Initialize the duck pool
    duck_pool = list(ducks)

    # Iterate over the number of shots
    for _ in range(ammo):
        # Check if the aim score is high enough to hit the duck
        if aim > 0:
            # Find the first duck to shoot
            for i in range(len(duck_pool)):
                if duck_pool[i] != 'X':
                    # Mark the duck as shot
                    duck_pool[i] = 'X'
                    break
        else:
            # If aim is 0, no shots can be made
            break

    # Join the list into a string and return
    return ''.join(duck_pool)

