        return word1[:2] + word2[:2].upper()

    # Define a function to generate a code for three words
    def generate_code_three_words(word1, word2, word3):
        return word1[:1] + word2[:1] + word3[:2].upper()

    # Define a function to generate a code for four words
    def generate_code_four_words(word1, word2, word3, word4):
        return word1[:1] + word2[:1] + word3[:1] + word4[:1].upper()

    # Iterate over each bird name in the input array
    codes = []
    for bird_name in arr:
        # Split the bird name by spaces and hyphens
        words = bird_name.replace('-', ' ').split()

        # Determine the number of words
        num_words = len(words)

        # Generate the code based on the number of words
        if num_words == 1:
            codes.append(generate_code(words[0]))
        elif num_words == 2:
            codes.append(generate_code_two_words(*words))
        elif num_words == 3:
            codes.append(generate_code_three_words(*words))
        elif num_words == 4:
            codes.append(generate_code_four_words(*words))
        else:
            raise ValueError("Invalid bird name format")

    return codes

