    if cat_pos == -1 or dog_pos == -1 or mouse_pos == -1:
        return 'boring without all three'

    # Calculate the distance between the cat and the mouse
    distance = abs(cat_pos - mouse_pos)

    # Check if the cat can catch the mouse
    if distance <= j:
        # Check if the cat can jump over the dog
        if dog_pos < cat_pos < mouse_pos or dog_pos < mouse_pos < cat_pos:
            return 'Caught!'
        else:
            return 'Protected!'
    else:
        return 'Escaped!'

def cat_mouse(x, j):
    # Identify the positions of the cat ('C'), dog ('D'), and mouse ('m')
    cat_pos = x.find('C')
    dog_pos = x.find('D')
    mouse_pos = x.find('m')

    # Check if all three characters are present
    if cat_pos == -1 or dog_pos == -1 or mouse_pos == -1:
        return 'boring without all three'

    # Determine if the cat can catch the mouse
    if cat_pos > dog_pos and cat_pos + j > mouse_pos:
        return 'Caught!'
    elif cat_pos > mouse_pos:
        return 'Caught!'
    elif cat_pos < dog_pos and (cat_pos + j <= mouse_pos or dog_pos + j <= mouse_pos):
        return 'Protected!'
    else:
        return 'Escaped!'
